+pub(super) fn settle(file: &mut ProjectFile, from: u32) -> Result<(), ProjectError> {
+    let mut ops: Vec<OpSlots> = Vec::new();
+    for dto in &file.entities {
+        let Some(op) = dto.operation.as_ref() else {
