+            return Err(corrupt(format!(
+                "operation '{}' measures a height from work offset #{bad} - the slots are G54 \
+                 to G59",
+                dto.name
+            )));
+        }
+        ops.push(OpSlots {
+            label: op.label.clone().unwrap_or_else(|| dto.name.clone()),
+            setup: op.setup.clone(),
+            slots: heights.into_iter().collect(),
+        });
+    }
+    if from >= 52 {
+        return Ok(());
+    }
