+    h.execute(&world, CreateSetup::new(&world, None, None).expect("materialize Setup1"));
+    for (slot, x, z) in [("G54", 0.0, 0.0), ("G55", 10.0, -2.0), ("G56", -5.0, -4.0)] {
+        let loc = Location { pos: Point3::new(x, 0.0, z), rot: IDENTITY_Q };
